CREATE TABLE catalogos (id BIGINT AUTO_INCREMENT PRIMARY KEY, codigo VARCHAR(60) NOT NULL UNIQUE, nombre VARCHAR(120) NOT NULL, descripcion VARCHAR(255), activo BOOLEAN NOT NULL DEFAULT TRUE, fecha_creacion TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE catalogo_valores (id BIGINT AUTO_INCREMENT PRIMARY KEY, catalogo_id BIGINT NOT NULL, codigo VARCHAR(60) NOT NULL, nombre VARCHAR(120) NOT NULL, orden INT NOT NULL DEFAULT 0, color_hex CHAR(7), activo BOOLEAN NOT NULL DEFAULT TRUE, CONSTRAINT fk_catalogo_valor_catalogo FOREIGN KEY (catalogo_id) REFERENCES catalogos(id), CONSTRAINT uk_catalogo_valor_codigo UNIQUE (catalogo_id, codigo));
INSERT INTO catalogos (codigo, nombre, descripcion) VALUES ('POSICION','Posiciones de juego','Posiciones configurables'),('ESTADO_DISPONIBILIDAD','Estados de disponibilidad','Disponibilidad deportiva y médica'),('ESTADO_CONVOCATORIA','Estados de convocatoria','Situación de convocatoria'),('TIPO_EVENTO_PARTIDO','Eventos de partido','Eventos de un encuentro'),('TIPO_LESION','Tipos de lesión','Clasificación clínica'),('ZONA_CUERPO','Zonas del cuerpo','Ubicación anatómica'),('FASE_EJERCICIO','Fases de entrenamiento','Momento metodológico'),('INTENSIDAD','Escala de intensidad','Carga planificada'),('ESTADO_ASISTENCIA','Estados de asistencia','Asistencia configurable'),('TIPO_ASPECTO_PARTIDO','Tipos de aspecto de partido','Fortalezas y oportunidades de mejora');
CREATE TABLE temporadas (id BIGINT AUTO_INCREMENT PRIMARY KEY, club_id BIGINT NOT NULL, nombre VARCHAR(100) NOT NULL, fecha_inicio DATE NOT NULL, fecha_fin DATE NOT NULL, activa BOOLEAN NOT NULL DEFAULT FALSE, CONSTRAINT fk_temporada_club FOREIGN KEY (club_id) REFERENCES clubes(id), CONSTRAINT uk_temporada_club_nombre UNIQUE (club_id, nombre), CONSTRAINT chk_temporada_fechas CHECK (fecha_fin >= fecha_inicio));
CREATE TABLE competiciones (id BIGINT AUTO_INCREMENT PRIMARY KEY, club_id BIGINT NOT NULL, temporada_id BIGINT, nombre VARCHAR(150) NOT NULL, organizador VARCHAR(150), formato VARCHAR(100), CONSTRAINT fk_competicion_club FOREIGN KEY (club_id) REFERENCES clubes(id), CONSTRAINT fk_competicion_temporada FOREIGN KEY (temporada_id) REFERENCES temporadas(id), CONSTRAINT uk_competicion_temporada_nombre UNIQUE (temporada_id, nombre));
CREATE TABLE sedes (id BIGINT AUTO_INCREMENT PRIMARY KEY, club_id BIGINT NOT NULL, nombre VARCHAR(150) NOT NULL, direccion VARCHAR(255), ciudad VARCHAR(100), latitud DECIMAL(10,7), longitud DECIMAL(10,7), CONSTRAINT fk_sede_club FOREIGN KEY (club_id) REFERENCES clubes(id));
CREATE TABLE perfiles_jugador (id BIGINT AUTO_INCREMENT PRIMARY KEY, equipo_usuario_id BIGINT NOT NULL UNIQUE, fecha_nacimiento DATE, documento_tipo VARCHAR(30), documento_numero VARCHAR(60), nacionalidad VARCHAR(100), pie_habil VARCHAR(30), altura_cm SMALLINT, peso_kg DECIMAL(5,2), contacto_emergencia_nombre VARCHAR(150), contacto_emergencia_telefono VARCHAR(30), observaciones_privadas TEXT, CONSTRAINT fk_perfil_jugador_integrante FOREIGN KEY (equipo_usuario_id) REFERENCES equipo_usuarios(id));
CREATE TABLE jugador_posiciones (id BIGINT AUTO_INCREMENT PRIMARY KEY, equipo_usuario_id BIGINT NOT NULL, posicion_id BIGINT NOT NULL, es_principal BOOLEAN NOT NULL DEFAULT FALSE, nivel_actual TINYINT, fecha_desde DATE, fecha_hasta DATE, observaciones VARCHAR(500), CONSTRAINT fk_jugador_posicion_integrante FOREIGN KEY (equipo_usuario_id) REFERENCES equipo_usuarios(id), CONSTRAINT fk_jugador_posicion_valor FOREIGN KEY (posicion_id) REFERENCES catalogo_valores(id));
CREATE TABLE disponibilidad_jugador (id BIGINT AUTO_INCREMENT PRIMARY KEY, equipo_usuario_id BIGINT NOT NULL, estado_id BIGINT NOT NULL, fecha_desde DATE NOT NULL, fecha_hasta DATE, porcentaje_disponible TINYINT NOT NULL DEFAULT 100, motivo VARCHAR(500), registrado_por BIGINT NOT NULL, fecha_registro TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_disponibilidad_integrante FOREIGN KEY (equipo_usuario_id) REFERENCES equipo_usuarios(id), CONSTRAINT fk_disponibilidad_estado FOREIGN KEY (estado_id) REFERENCES catalogo_valores(id), CONSTRAINT fk_disponibilidad_registrador FOREIGN KEY (registrado_por) REFERENCES usuarios(id));
CREATE TABLE lesiones (id BIGINT AUTO_INCREMENT PRIMARY KEY, equipo_usuario_id BIGINT NOT NULL, tipo_lesion_id BIGINT NOT NULL, zona_cuerpo_id BIGINT, fecha_inicio DATE NOT NULL, fecha_alta_estimada DATE, fecha_alta_real DATE, severidad TINYINT, diagnostico TEXT, tratamiento TEXT, restricciones TEXT, registrado_por BIGINT NOT NULL, CONSTRAINT fk_lesion_integrante FOREIGN KEY (equipo_usuario_id) REFERENCES equipo_usuarios(id), CONSTRAINT fk_lesion_tipo FOREIGN KEY (tipo_lesion_id) REFERENCES catalogo_valores(id), CONSTRAINT fk_lesion_zona FOREIGN KEY (zona_cuerpo_id) REFERENCES catalogo_valores(id), CONSTRAINT fk_lesion_registrador FOREIGN KEY (registrado_por) REFERENCES usuarios(id));
CREATE TABLE sanciones (id BIGINT AUTO_INCREMENT PRIMARY KEY, equipo_usuario_id BIGINT NOT NULL, partido_id BIGINT, fecha_inicio DATE NOT NULL, fecha_fin DATE, partidos_pendientes SMALLINT, motivo VARCHAR(500) NOT NULL, activa BOOLEAN NOT NULL DEFAULT TRUE, CONSTRAINT fk_sancion_integrante FOREIGN KEY (equipo_usuario_id) REFERENCES equipo_usuarios(id), CONSTRAINT fk_sancion_partido FOREIGN KEY (partido_id) REFERENCES partidos(id));
CREATE TABLE convocatorias (id BIGINT AUTO_INCREMENT PRIMARY KEY, partido_id BIGINT NOT NULL, equipo_usuario_id BIGINT NOT NULL, estado_id BIGINT NOT NULL, motivo_no_convocatoria VARCHAR(500), respondida_en TIMESTAMP NULL, CONSTRAINT fk_convocatoria_partido FOREIGN KEY (partido_id) REFERENCES partidos(id) ON DELETE CASCADE, CONSTRAINT fk_convocatoria_integrante FOREIGN KEY (equipo_usuario_id) REFERENCES equipo_usuarios(id), CONSTRAINT fk_convocatoria_estado FOREIGN KEY (estado_id) REFERENCES catalogo_valores(id), CONSTRAINT uk_convocatoria_partido_jugador UNIQUE (partido_id, equipo_usuario_id));
CREATE TABLE aspectos_partido (id BIGINT AUTO_INCREMENT PRIMARY KEY, partido_id BIGINT NOT NULL, tipo_id BIGINT NOT NULL, titulo VARCHAR(180) NOT NULL, descripcion TEXT, prioridad TINYINT NOT NULL DEFAULT 3, resuelto_en TIMESTAMP NULL, creado_por BIGINT NOT NULL, fecha_creacion TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_aspecto_partido FOREIGN KEY (partido_id) REFERENCES partidos(id) ON DELETE CASCADE, CONSTRAINT fk_aspecto_tipo FOREIGN KEY (tipo_id) REFERENCES catalogo_valores(id), CONSTRAINT fk_aspecto_autor FOREIGN KEY (creado_por) REFERENCES usuarios(id));
CREATE TABLE entrenamiento_aspectos (entrenamiento_id BIGINT NOT NULL, aspecto_partido_id BIGINT NOT NULL, objetivo_especifico TEXT, PRIMARY KEY (entrenamiento_id, aspecto_partido_id), CONSTRAINT fk_entrenamiento_aspecto_entrenamiento FOREIGN KEY (entrenamiento_id) REFERENCES entrenamientos(id) ON DELETE CASCADE, CONSTRAINT fk_entrenamiento_aspecto_aspecto FOREIGN KEY (aspecto_partido_id) REFERENCES aspectos_partido(id) ON DELETE CASCADE);
CREATE TABLE alineaciones_partido (id BIGINT AUTO_INCREMENT PRIMARY KEY, partido_id BIGINT NOT NULL, equipo_usuario_id BIGINT NOT NULL, posicion_id BIGINT, titular BOOLEAN NOT NULL DEFAULT FALSE, capitan BOOLEAN NOT NULL DEFAULT FALSE, dorsal SMALLINT, minuto_ingreso SMALLINT, minuto_salida SMALLINT, CONSTRAINT fk_alineacion_partido FOREIGN KEY (partido_id) REFERENCES partidos(id) ON DELETE CASCADE, CONSTRAINT fk_alineacion_integrante FOREIGN KEY (equipo_usuario_id) REFERENCES equipo_usuarios(id), CONSTRAINT fk_alineacion_posicion FOREIGN KEY (posicion_id) REFERENCES catalogo_valores(id), CONSTRAINT uk_alineacion_partido_jugador UNIQUE (partido_id, equipo_usuario_id));
CREATE TABLE evaluaciones_partido_jugador (id BIGINT AUTO_INCREMENT PRIMARY KEY, partido_id BIGINT NOT NULL, equipo_usuario_id BIGINT NOT NULL, posicion_id BIGINT, minutos_jugados SMALLINT NOT NULL DEFAULT 0, calificacion DECIMAL(3,1), observaciones TEXT, evaluado_por BIGINT NOT NULL, CONSTRAINT fk_evaluacion_partido FOREIGN KEY (partido_id) REFERENCES partidos(id) ON DELETE CASCADE, CONSTRAINT fk_evaluacion_integrante FOREIGN KEY (equipo_usuario_id) REFERENCES equipo_usuarios(id), CONSTRAINT fk_evaluacion_posicion FOREIGN KEY (posicion_id) REFERENCES catalogo_valores(id), CONSTRAINT fk_evaluacion_autor FOREIGN KEY (evaluado_por) REFERENCES usuarios(id), CONSTRAINT uk_evaluacion_partido_jugador UNIQUE (partido_id, equipo_usuario_id));
CREATE TABLE metricas_definicion (id BIGINT AUTO_INCREMENT PRIMARY KEY, club_id BIGINT, codigo VARCHAR(60) NOT NULL, nombre VARCHAR(150) NOT NULL, unidad VARCHAR(30) NOT NULL, descripcion VARCHAR(500), direccion_optima VARCHAR(20) NOT NULL DEFAULT 'MAYOR_MEJOR', activa BOOLEAN NOT NULL DEFAULT TRUE, CONSTRAINT fk_metrica_club FOREIGN KEY (club_id) REFERENCES clubes(id), CONSTRAINT uk_metrica_club_codigo UNIQUE (club_id, codigo));
CREATE TABLE mediciones_jugador (id BIGINT AUTO_INCREMENT PRIMARY KEY, equipo_usuario_id BIGINT NOT NULL, metrica_id BIGINT NOT NULL, fecha DATE NOT NULL, valor DECIMAL(12,3) NOT NULL, contexto VARCHAR(255), registrado_por BIGINT NOT NULL, CONSTRAINT fk_medicion_integrante FOREIGN KEY (equipo_usuario_id) REFERENCES equipo_usuarios(id), CONSTRAINT fk_medicion_metrica FOREIGN KEY (metrica_id) REFERENCES metricas_definicion(id), CONSTRAINT fk_medicion_registrador FOREIGN KEY (registrado_por) REFERENCES usuarios(id));
CREATE TABLE ejercicio_tags (ejercicio_id BIGINT NOT NULL, valor_id BIGINT NOT NULL, PRIMARY KEY (ejercicio_id, valor_id), CONSTRAINT fk_ejercicio_tag_ejercicio FOREIGN KEY (ejercicio_id) REFERENCES ejercicios(id) ON DELETE CASCADE, CONSTRAINT fk_ejercicio_tag_valor FOREIGN KEY (valor_id) REFERENCES catalogo_valores(id));
