ALTER TABLE partidos ADD COLUMN competencia_id BIGINT NULL, ADD COLUMN sede_id BIGINT NULL, ADD COLUMN jornada VARCHAR(50) NULL, ADD COLUMN estado VARCHAR(30) NOT NULL DEFAULT 'PROGRAMADO', ADD COLUMN formacion VARCHAR(50) NULL, ADD CONSTRAINT fk_partido_competencia FOREIGN KEY (competencia_id) REFERENCES competiciones(id), ADD CONSTRAINT fk_partido_sede FOREIGN KEY (sede_id) REFERENCES sedes(id);
ALTER TABLE partido_eventos ADD COLUMN tipo_id BIGINT NULL, ADD CONSTRAINT fk_evento_tipo FOREIGN KEY (tipo_id) REFERENCES catalogo_valores(id);
